Matching Ayahs
- = 알리프, 라암, 미임. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = 그들은 그들의 주님으로부터 올바른 인도함을 받은 자들이며, 그들은 성공한 자들이다. 2:5; 31:5
- = 이스라엘 자손들아! 내가 너희에게 베푼 은혜와 내가 너희를 온 세상(민족) 위에 우위에 두었던 것을 기억하라. 2:47; 2:122
- = 그것은 이미 지나간 한 공동체이다. 그들에게는 그들이 얻은 것이 있고, 너희에게는 너희가 얻은 것이 있다. 그리고 너희는 그들이 행했던 것에 대해 묻지 않을 것이다. 2:134; 2:141
- = 그들은 그 안에 영원히 머물며, 그들에게 형벌이 가볍게 되지 않으며, 그들에게 유예도 주어지지 않는다. 2:162; 3:88
- = 그러나 그 후에 회개하고 스스로를 바로잡는 자들은 제외라. 실로 알라시는 관용과 자비로 충만하시다. 3:89; 24:5
- = 그러나 불신하고 우리의 징표들을 부정하는 자들, 그들은 지옥의 동료들이다. 5:10; 5:86
- = 그리고 그들의 주님의 징표들 중 어떤 징표가 그들에게 오더라도 그들은 그것으로부터 외면할 뿐이다. 6:4; 36:46
- = 그리고 너보다 먼저 선지자们也 조롱을 당했으나, 그들을 조롱했던 자들은 그들이 조롱하던 바로 그것에 포위되었다. 6:10; 21:41
- = 말하라: "내가 만일 내 주님을 거역한다면, 위대한 날의 형벌을 두려워하노라." 6:15; 39:13
- = 그러자 지진이 그들을 덮쳤고, 그들은 그들의 집 안에서 엎드려 죽은 채가 되었다. 7:78; 7:91
- = 그래서 그(모세)가 그의 지팡이를 던지니, 보라, 그것은 분명한 뱀이 되었다. 7:107; 26:32
- = 그리고 그가 그의 손을 내밀자, 보라, 그것은 보는 자들에게 하얗게(빛나며) 보였다. 7:108; 26:33
- = 그들이 말하길: "우리는 온 세계의 주님을 믿었노라." 7:121; 26:47
- = 모세와 아론의 주님. 7:122; 26:48
- = 그리고 나는 그들에게 유예를 주리라. 실로 나의 계획은 확고하다. 7:183; 68:45
- = 그분은 그의 선지자를 올바른 인도와 진리의 종교와 함께 보내신 분이시니, 그것을 모든 종교 위에 우위에 두시려 함이라, 비록 다신교도들이 싫어할지라도. 9:33; 61:9
- = 예언자여, 불신자들과 위선자들과 싸우고 그들에게 엄격하라. 그들의 거처는 지옥이며, 그 얼마나 나쁜 운명인가! 9:73; 66:9
- = 그리고 그들은 말하길: "만일 너희가 진실하다면, 이 약속이 언제인가?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = 그리고 우리는 모세를 우리의 징표들과 분명한 권한과 함께 보냈노라. 11:96; 40:23
- = 그리고 우리는 모세에게 성경을 주었으나, 그것에 대해 의견이 갈렸다. 그리고 네 주님으로부터 선행된 말씀이 없었다면, 그들 사이에 판결이 내려졌을 것이다. 그리고 실로 그들은 그것에 대해 의심하고 있다. 11:110; 41:45
- = 그것은 알라에게 어렵지 않다. 14:20; 35:17
- = "내가 그(아담)를 완성하고 내 영혼을 그에게 불어넣으면, 너희는 그에게 엎드려 절하라." 15:29; 38:72
- = 그러자 천사들이 모두 함께 엎드려 절했다. 15:30; 38:73
- = (알라가) 말하길: "그러면 그곳에서 나가라, 실로 너는 추방된 자이다." 15:34; 38:77
- = (이블리스가) 말하길: "나의 주님, 그러면 그들이 부활하는 날까지 저에게 유예를 주소서." 15:36; 38:79
- = (알라가) 말하길: "그러면 실로 너는 유예를 받은 자들 중 하나이다." 15:37; 38:80
- = 정해진 시간의 날까지." 15:38; 38:81
- = 그들 중 당신의 선택받은 종들은 제외라. 15:40; 38:83
