- 그들의 보상은 그들의 주님께 있으며, 그들에게는 두려움이 없고 그들은 슬퍼하지 아니하리라. (أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:62; 2:112; 2:262; 2:274; 2:277
- 그들은 땅 위를 여행하며 그들 이전의 사람들의 끝이 어떻게 되었는지 본다. (يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن) 30:9; 30:42; 35:44; 40:82; 47:10
- 땅 위를 여행하며 그들 이전의 사람들의 끝이 어떻게 되었는지 본다. (فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ) 30:9; 30:42; 35:44; 40:82; 47:10
- 알라에 대해 거짓을 꾸미거나 부정하는 자보다 더 불의한 자가 누구이겠는가? (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ) 6:21; 6:93; 7:37; 10:17; 29:68
- 알라께서 어떤 일을 결정하시면, 그분은 그것에 "있어라"고 말씀하실 뿐, 그것이 있게 되느니라. (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
- 알라 외에 너희에게는 어떤 보호자도, 어떤 도우미도 없노라. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- 나는 그들의 죄악을 용서하고 그들을 그 아래로 강물이 흐르는 낙원으로 들어가게 하리라. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- 우리는 그들을 그 아래로 강물이 흐르는 낙원으로 들어가게 하리니, 그곳에서 영원히 거하리라. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- 그대의 주님은 그분의 길에서 누가 벗어났는지를 가장 잘 아시며, 또한 가장 잘 아신다. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- 너희는 보이지 않는 것과 보이는 것을 아는 분께로 돌려지고, 그분은 너희가 행하던 것을 너희에게 알리시리라. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- 그들은 너희의 아들들을 죽이고 너희의 여자들을 살려 두었도다; 그 안에 너희 주님으로부터 큰 시험이 있었느니라. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- 실로 그대의 주님은 그분의 길에서 누가 벗어나는지를 가장 잘 아시며, 또한 그분은. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- 알라, 그분께 하늘과 땅에 있는 모든 것이 속하도다. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- 너희 이전의 많은 민족들 가운데, 진과 인간들 가운데. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- 알라를 경배하라, 그분 외에 너희에게 신은 없나니, 너희는 두려워하지 아니하느냐? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- 우리는 그들이 그것을 이해하지 못하도록 그들의 마음에 덮개를 두었고, 그들의 귀에는 무거움을 두었노라. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- 그분은 부활의 날에 그들이 의견을 달리했던 것에 대해 그들 사이를 판결하시리라. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- 그가 말하길: "내 백성들아! 너희는 어떻게 생각하느냐? 만일 내가 내 주님으로부터 분명한 증거 위에 있다면?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- 이는 너희 손이 앞서 보낸 것 때문이며, 알라는 종들에게 결코 불의하지 아니하시니라. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- 그들에게는 현세에서 수치가 있고, 내세에서는 큰 형벌이 있느니라. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- 하늘과 땅에 있는 모든 것은 알라의 것이며, 알라는 보호자로서 충분하시도다. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- 믿고 선한 일을 행한 자들 외에는; 그들에게는 끊임없는 보상이 있느니라. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- 네가 알지 못하는 것을 나에게 짝짓지 말라; 그들을 순종하지 말라. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- 실로 이것은 훈계니, 원하는 자는 그의 주님께로 가는 길을 취하라. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- 감사하는 자는 자신을 위해 감사하며, 배은망덕하는 자는. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- 기도를 드리고, 자카트를 내며, 내세를 확신하는 자들. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- 이브라힘, 이스마일, 이스하크, 야쿠브와 그 자손들, 그리고 무사와 이사에게 주어진 것. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- 무리로, 그들이 거기에 이르면, 그 문이 열리고, 그 수호자들이 그들에게 말하노라. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- 알라께서 너희의 맹세 속의 무의미한 말로 너희를 책망하지 않으시나, 그분은 너희를 책망하시느니라. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- 자비, 그들은 그것에 기뻐하나, 만약 그들의 손이 앞서 보낸 것으로 인해 재앙이 그들에게 닿으면. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- 그 아래로 강물이 흐르는 낙원, 그곳에서 영원히 거할 것이며, 행위자들의 보상이 얼마나 아름다운가! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- 알라는 하늘과 땅에 있는 모든 것을 아시며, 알라는. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- 알라에게 순종하고 사자에게 순종하라; 그러나 너희가 돌아선다면, 그에게는 (의무가) 있느니라. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- 그들에게는 그들의 주님께 그들의 보상이 있으며, 그들에게는 두려움이 없고, 그들은. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- 그리고 그들이 말하길: "우리가 뼈와 부스러기가 되면, 정말로 새로운 창조물로 부활할 것인가?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- 그들은 알라 외에 자신들을 위한 어떤 보호자나 도우미도 찾지 못하느니라. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "네가 얼마나 머물렀느냐?" 그가 말하길: "나는 하루나 하루의 일부를 머물렀노라." 그가 말하길. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- 부활의 날까지 영원히, 알라 외에 너희에게 가져올 수 있는 신이 누구이겠는가? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- 선행을 하는 자, 남자든 여자든, 그리고 그는 믿는 자라면. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- 알라의 길에서 사람들을 막고, 그것을 비틀게 하려 하며, 내세를 믿지 않는 자들. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- 원하는 곳에서 먹으라, 그러나 이 나무에 가까이 하지 말라, 그러지 않으면 너희는 불의한 자들이 되리라. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- 말하라: "내 백성들아! 너희는 너희의 처지에 따라 행동하라, 나도 행동하리니, 곧 너희가 알게 되리라." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- 실로 손해를 보는 자들은 부활의 날에 자신과 가족을 잃은 자들이니, 보라. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- 올바른 길을 가는 자는 자신을 위해 가는 것이며, 방황하는 자는 자신을 위해 방황하는 것이니, 그리고. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- 그리고 불신자들이 말하길: "왜 그에게 그의 주님으로부터 징표가 내려지지 아니하였는가?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- 너희를 위해 밤을 휴식하게 하고, 낮을 보게 하신 분, 실로. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- 그 날이 오기 전에, 그 날은 매매도 우정도 없으리라. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- 그들의 동료에게 광기가 없음을 생각하게 하려 함이라; 그는 분명한 경고자일 뿐이니라. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- 그곳에 영원히 거하며, 그들에게 형벌이 경감되지 않고, 그들에게 유예도 주어지지 않느니라. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- 우리가 그들 중 일부에게 향락으로 준 것에 네 눈을 돌리지 말라. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- 사람들에게 그들의 물건을 속여 빼앗지 말며, 땅에서 부패를 퍼뜨리지 말라. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
