- 자신을 위함이며, 누구든지 방황하는 자는 자신을 해롭게 할 뿐이니라. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- 어찌하여 그의 주님으로부터 그에게 한 표징이 내려지지 아니하였는가? 말하라: 실로. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- 믿고 선한 일을 하는 자들에게는 끊임없는 보상이 있느니라. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- 너는 산 자를 죽은 자로부터 나오게 하고 죽은 자를 산 자로부터 나오게 하노라. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- 알라가 내려준 것으로 판결하지 아니하는 자, 그들은 바로. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- 그분이 하늘과 땅과 그 사이에 있는 모든 것을 여섯 날에 창조하셨노라. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- 실로 알라는 인간에게 은혜로우시나 대다수는. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- 알라는 그들에게 불의를 행하지 아니하였으나 그들이 스스로 불의를 행하였노라. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- 그가 너희 죄를 용서해 주시고 너희를 그 아래로 강들이 흐르는 천국으로 들어가게 하리라. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- 그분이 너희에게 금하신 것은 죽은 고기, 피, 돼지 고기, 그리고 알라 외의 이름으로 도살된 것이니라. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- 실로 나는 주님을 거역할 경우 위대한 날의 벌을 두려워하노라. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- 그러나 그들에게 지식이 온 후에, 그들 사이의 시기로 인하여. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- 그들은 기도를 드리고 우리가 그들에게 준 것에서 은밀히 또 공개적으로 베푸노라. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- 알라 외에 우리에게 유익도 해로움도 주지 못하는 것을 우리가 숭배하리요? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- 그들은 너에게 내려진 것과 너 이전에 내려진 것을 믿노라. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- 알라가 하늘로부터 물을 내려보내심을 너는 보지 아니하느냐? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- 그분이 어떤 일을 결정하시면 단지 그것에 말하길: 있어라, 그러면 있느니라. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- 그리고 마드얀에 그들의 형제 수아이브를 (보내었노라). 그가 말하길: 내 백성아, 알라를 경배하라. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- 그것은 우리가 너에게 계시하는 보이지 않는 소식 중 하나이며, 너는 그것을 알지 못하였노라. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- 그들의 기한이 이르면 그들은 한 시간도 늦추지도 앞당기지도 못하느니라. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- 사탄의 발걸음을 따르지 말라, 실로 그는 너희에게 명백한 적이니라. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- 인간 중에는 지식 없이 알라에 대해 논쟁하는 자가 있느니라. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- 알라는 그분이 원하시는 자에게 주시며, 알라는 위대한 은혜의 주님이시니라. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- 각 영혼은 그가 행한 대로 완전한 보상을 받을 것이며, 그들은 불의를 당하지 아니하리라. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- 알라가 금하신 생명을 정당한 이유 없이 죽이지 말라. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- 그분이 어떤 일을 결정하시면 단지 그것에 말하길: 있어라. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- 너희는 지옥의 문으로 들어가라, 그 속에 영원히 거하리라. 교만한 자들의 거처가 얼마나 나쁜지! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- 너는 성경의 일부를 받은 자들을 보지 아니하였느냐? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- 그들에게는 그 아래로 강들이 흐르는 천국이 있나니, 그들 속에 영원히 거하리라. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- 내 백성아, 너희의 처지에 따라 행동하라, 나도 행동하리니, 곧 너희가 알게 되리라. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- 알라와 그의 사도에게 반항하는 자, 그에게는 지옥의 불이 있나니, 그 속에 영원히 거하리라. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- 우리는 그들의 마음에 덮개를 씌웠노니, 그들이 그것을 이해하지 못하게 하고, 그들의 귀에 멍하게 하였노라. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- 어떤 마을에 경고자를 보내면 그곳의 부유한 자들이 말하길: 우리는. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- 그들이 말하길: 우리를 위해 당신의 주님께 기도하여 그것이 무엇인지 우리에게 밝혀 주소서. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- 그들은 반드시 말하리라: 알라시라. 말하라: 모든 찬미는 알라께 있나니, 그러나 그들 대다수는. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- 그의 백성의 대답은 단지: 그들을 내쫓으라, 하는 것이었노라. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- 그 아래로 강들이 흐르며, 그들 속에 영원히 거하리라, 그것이 위대한 성공이니라. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- 그들은 그들의 주님으로부터 바른 길 위에 있으며, 그들은 성공한 자들이니라. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- 그에게 굴욕적인 벌이 이르고 그에게 영원한 벌이 내리는 자. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- 땅 위를 여행하며 (진리를) 부정한 자들의 종말이 어찌되었는지를 보라. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- 그들은 그들의 손이 앞서 보낸 것으로 인해 그것을 영원히 바라지 아니할 것이며, 알라는 불의한 자들을 잘 아시느니라. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- 그분은 그분의 길에서 누가 방황하는지 가장 잘 아시며, 그분은 가장 잘 아시느니라. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- 실로 알라는 나의 주님이시며 너희의 주님이시니, 그러므로 그분을 경배하라, 이것이 곧바른 길이니라. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- 그분은 인간에게 은혜로우시나 대다수는 감사하지 아니하느니라. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- 하늘과 땅과 그 사이에 있는 것들을 우리가 진리와 정해진 기한으로 창조하였을 뿐이니라. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- 그들을 내버려두어 그들이 헛된 말에 빠져 놀게 하라, 그들이 약속된 그 날을 만날 때까지. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- 그들이 믿는 자들을 만나면 말하길: 우리는 믿노라, 그러나 그들이 서로 따로 있을 때는. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- 그들은 토라와 복음과 그들의 주님으로부터 그들에게 내려진 것을 지키노라. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- 그분은 그들 앞에 있는 것과 그들 뒤에 있는 것을 아시며, 그들은 그것을 지식으로 감쌀 수 없느니라. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- 그리고 그분은 하늘과 땅을 여섯 날에 창조하신 분이시니라. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- 실로 그 속에 너희를 위한 표징이 있나니, 만약 너희가 믿는 자라면. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- 인간에게 올바른 길이 왔을 때 그들이 믿지 못하게 한 것이 무엇이냐? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- 그들이 알라에게 동반자를 두어 그분의 길에서 벗어나게 하려 하였노라. 말하라: 향락하라. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- 그들은 그들 가운데서 경고자가 온 것에 놀라며, 불신자들이 말하길: 이는. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- 실로 너의 주님은 그분의 길에서 누가 방황하는지 가장 잘 아시느니라. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- 사람들에게 보이기 위해 자신의 재산을 낭비하며 알라를 믿지 아니하는 자와 같도다. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- 그 날이 오기 전에 우리가 너희에게 준 것으로 베풀라. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- 그분이 하늘과 땅에 있는 모든 것을 너희에게 복종시키셨노라. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- 그리고 우리는 실로 너희가 우리를 부르는 것에 대해 의심 중에 있노라. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- 실로 너의 주님은 그분이 원하시는 자에게 양식을 넓혀 주시고 또 좁히시느니라. 실로 그분은. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- 하늘과 땅과 그 사이에 있는 모든 것의 주님, 만약 너희가 확신하는 자라면. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- 우리는 알라를 믿으며, 우리에게 내려진 것과 (아브라함, 이스마엘, 이삭, 야곱과 그 후손들에게) 내려진 것을 믿노라. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- 불의한 자들을 큰 외침이 덮쳐, 그들은 그들의 집에서 쓰러져 있었노라. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- 그 여성들이 자신들에 대해 행하는 것에 대해 너희에게 책임이 없느니라. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- 너의 주님은 그분의 길에서 누가 방황하는지 가장 잘 아시며, 그분은. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- 그분의 명령으로 영(계시)을 그분이 원하시는 종에게 내리시느니라. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- 그리고 우리는 마리아의 아들 예수에게 명백한 표적들을 주었고 성령으로 그를 강하게 하였노라. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- 부활의 날에 그들 사이에 그들이 의견 차이를 보였던 것에 대해 심판하게 하려 함이라. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- 우리는 그 (도시)를 위아래로 뒤집었고 그들 위에 구워진 진흙 돌을 비처럼 내렸노라. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- 그들에게는 네가 경고하든 경고하지 아니하든 같으니, 그들은 믿지 아니하리라. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- 인간을 제외하고, 만약 너희가 진실하다면 죽음을 바라라. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- 알라를 (경배하라), 그분 외에 너희에게 신은 없노라. 그럼에도 너희는 두려워하지 아니하느냐? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- 우리가 그들에게 약속한 것 중 일부를 네게 보여주든지, 혹은 너를 죽이든지, 그들의 귀환은 우리에게 있느니라. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- 그들이 말하길: 우리가 죽어 흙과 뼈가 된 후에, 우리가 정말로 부활될 것인가? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- 실로 은혜는 알라의 손에 있나니, 그분이 원하시는 자에게 주시며, 알라는. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- 너희는 보이지 않는 것과 보이는 것을 아는 분께로 돌아가리니, 그분이 너희가 행하던 것을 너희에게 알려 주시리라. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- 믿는 자들아, 알라가 너희에게 베푼 은혜를 기억하라, 그때에. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- 우리는 너 이전에도 계시를 내린 남자들만을 보내었노라. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- 그가 그의 죄를 용서해 주시고 그를 그 아래로 강들이 흐르는 천국으로 들어가게 하리라. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- 병들거나 여행 중인 자는 다른 날수로 (금식) 보충하라. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- 그들은 추측만을 따를 뿐이며, 그들은 단지 억측할 뿐이니라. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- 알라와 내세를 바라는 자에게는 좋은 모범이 있느니라. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- 우리가 하늘과 땅과 그 사이에 있는 모든 것을 진리로 창조하였을 뿐이니라. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- 네 손을 네 옷깃에 넣으라, 그것이 아무 병 없이 하얗게 나오리라. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- 그분은 그분의 자비로 원하시는 자를 선택하시며, 알라는 위대한 은혜의 주님이시니라. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- 알라께서 하늘과 땅의 왕권을 소유하심을 너는 알지 못하느냐? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- 너희가 너희 자신을 위해 앞서 보내는 모든 선한 일은 너희가 알라 곁에서 찾으리라. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- 네가 어디에서 나오든, 네 얼굴을 성스러운 사원 쪽으로 돌리라. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- 너희 이전의 자들은 (지나갔으며), 너는 알라의 법도에서 어떤 변화도 발견하지 못하리라. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- 하늘과 땅에 있는 모든 것을 소유하신 분이시라. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- 어떤 여성도 잉태하거나 출산하지 아니하나니, 오직 그분의 지식에 따라라. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- 그분이 밤과 해와 달을 복종케 하셨으니, 각각 정해진 기한까지 운행하느니라. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- 그 아래로 강들이 흐르며, 그들 속에 영원히 거하리라, 그것이 보상이니라. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- 그가 말하길: 아니라, 너희 영혼이 너희에게 어떤 일을 꾸몄구나, 그러나 인내가 아름다우니라. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- 하늘과 땅에 있는 것, 그리고 알라는. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- 그들에게 어떤 사자가 와도 그들은 그를 조롱하였노라. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- 그들이 말하길: 오 모세야, 네가 던질 것인가, 아니면 우리가 던질 것인가? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- 그분이 너희를 죽게 하시고, 너희 중 어떤 이는 가장 나쁜 나이로 되돌려 보내시니, 이는. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- 그들에게는 그들의 주님 곁에 그 아래로 강들이 흐르는 천국이 있나니, 그들 속에 영원히 거하리라. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- 그리고 우리는 그들의 마음에 덮개를 씌웠노니, 그들이 그것을 이해하지 못하게 하고, 그들의 귀에 멍하게 하였노라. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- 실로 알라의 약속은 진실하나, 그들 대다수는 알지 못하느니라. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- 그것은 그들이 알라와 그의 사도에게 반항하였기 때문이며, 알라에게 반항하는 자는. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- 그분이 그들을 부르시는 날, 말씀하시길: 너희가 주장했던 나의 동반자들이 어디 있느냐? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- 그들이 알라가 하늘과 땅을 창조하신 것을 보지 아니하였느냐? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (그분이) 너를 흙에서, 그 다음 정액에서, 그 다음. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- 그들이 말하리라: 우리 주님, 어찌하여 우리에게 사자를 보내지 아니하셨나이까, 그러면 우리가 주님의 표적들을 따랐을 텐데. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- 그 후 그들은 그들의 주님께로 돌아가리니, 그분이 그들이 행하던 것을 그들에게 알려 주시리라. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- 그들은 그것에 대해 어떤 지식도 없으며, 그들은 추측만을 따를 뿐이니라. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- 실로 우리는 조상들을 한 종교 위에서 발견하였고, 우리는 그들의 발자취를 따르는 자들이라. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- 성경을 받은 자들이 (의견 차이를 보인 것은) 그들에게 지식이 온 후라. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- 그리고 아브라함이 말하길: 나의 주님, 이 도시를 안전하게 하소서. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- 그분이 너희에게 청각, 시각, 심장을 주셨으나, 너희는 조금밖에 감사하지 아니하느니라. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- 알라의 표적들에 대해 그들에게 온 어떤 권위도 없이 논쟁하는 자들. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- 그러므로 아브라함의 순수한 종교를 따르라, 그는 다신교도가 아니었노라. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- 그리고 우리가 너희를 파라오의 백성에게서 구원하였을 때, 그들이 너희에게 최악의 고통을 내렸노라. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- 그것이 올바른 종교이나, 대다수의 사람들은 알지 못하느니라. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- 알라가 너희를 위해 하늘과 땅에 있는 것들을 복종케 하심을 너는 보지 아니하느냐? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- 불신자들이 말하리라: 이것은 명백한 마술에 불과하도다. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- 우리의 명백한 표적들이 그들에게 낭송될 때, 불신자들이 말하노라. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- 그 아래로 강들이 흐르는 영원한 천국, 그들 속에 영원히 거하리라. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- 그분이 원하시는 것을 창조하시나니, 실로 알라는 모든 것에 전능하시니라. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- 그분이 너희의 죄를 용서해 주시고 너희를 정해진 기한까지 지체시키려 함이라. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- 너희는 우리가 조상들을 숭배하던 것에서 우리를 돌리려 하느냐? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- 너의 주님이 천사들에게 말하길: 실로 나는 진흙으로 인간을 창조하리라. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- 그분은 자신의 자비 앞에 바람을 길한 소식으로 보내시는 분이시라. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- 말하라: 땅 위를 여행하며 종말이 어찌되었는지를 보라. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- 하늘과 땅의 창조와 밤과 낮의 교대 속에 (표징들이 있느니라). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- 누가 알라에게 좋은 빚을 내어 그분이 그것을 배가시켜 주리요? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- 그러므로 그들 사이에 알라가 내려준 것으로 판결하고, 그들의 욕망을 따르지 말라. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- 그들이 기다리는 것은 천사들이 그들에게 오거나, 혹은 너의 주님의 명령이 오는 것뿐이냐? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- 실로 알라에 대해 거짓말을 꾸미는 자들은 성공하지 못하리라. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- 파라오의 백성과 그들 이전의 자들의 경우와 같이, 그들이 우리의 표적들을 부정하였노라. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- 그리고 믿고 선한 일을 하는 자들에게 기쁜 소식을 전하노니, 그들에게 보상이 있느니라. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- 알라는 그분이 원하시는 종에게 양식을 넓혀 주시고 또 좁히시느니라. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- 너희는 보이지 않는 것과 보이는 것을 아는 분께로 돌아가리니, 그분이 너희가 행하던 것을 너희에게 알려 주시리라. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- 그리고 혈족 관계자들은 알라의 성경에서 서로가 일부에게 더 가까우니라. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
""";
